function compactLocale(language){
  return {
    ...en,
    meta:language.meta,
    controls:language.controls,
    hero:language.hero,
    status:language.status,
    actions:language.actions,
    release:language.release,
    features:language.features,
    classic:{...en.classic,...language.classic},
    workflow:language.workflow,
    roadmap:language.roadmap
  };
}

